import{_ as a}from"./chunks/isaac-sim.fbmzTwGQ.js";import{_ as i,o as t,c as e,a5 as o}from"./chunks/framework.BMR-TWOq.js";const m=JSON.parse('{"title":"Isaac Sim","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/simulator/isaac-sim.md","filePath":"ko/software/simulator/isaac-sim.md","lastUpdated":1794576042000}'),d={name:"ko/software/simulator/isaac-sim.md"};function l(h,s,n,r,c,p){return t(),e("div",null,[...s[0]||(s[0]=[o('<h1 id="isaac-sim" tabindex="-1">Isaac Sim <a class="header-anchor" href="#isaac-sim" aria-label="Permalink to &quot;Isaac Sim&quot;">​</a></h1><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p><strong>RBQ 4족 보행 로봇을 위한 Isaac Sim 시뮬레이터.</strong></p><p>Isaac Sim은 <a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo</a>, <a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo</a>처럼 NVIDIA Isaac Sim 물리 위에서 <strong>RBQ 소프트웨어 스택 전체</strong>(Motion / Vision)를 실행합니다. 같은 토픽으로 실행 중인 RBQ 스택에 DDS 피어로 참여하므로 로봇 소프트웨어를 고치지 않고 그대로 씁니다. 로봇 모델은 <a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab</a> 학습 환경과 같고, 계단·경사로·험지가 있는 USD 월드를 함께 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Isaac Sim</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+a+`" alt="Isaac Sim" width="600"></td></tr></tbody></table><h2 id="요구-사항" tabindex="-1">요구 사항 <a class="header-anchor" href="#요구-사항" aria-label="Permalink to &quot;요구 사항&quot;">​</a></h2><ul><li>NVIDIA RTX GPU, 여유 디스크 약 30 GB</li><li>Ubuntu 22.04</li><li>Isaac Sim 5.1.0과 Isaac Lab. 아래 설치 스크립트가 Isaac Lab과 같은 conda 환경(<code>rbq-lab</code>)에 설치합니다</li></ul><h2 id="구성" tabindex="-1">구성 <a class="header-anchor" href="#구성" aria-label="Permalink to &quot;구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>경로</th><th>설명</th></tr></thead><tbody><tr><td><code>rbq_simulator/rbq_sim/rbq_sim/</code></td><td>시뮬레이터 소스 (Python)</td></tr><tr><td><code>rbq_simulator/rbq_sim/worlds/</code></td><td>패키지에 포함된 USD 월드</td></tr><tr><td><code>rbq_simulator/rbq_sim/scripts/</code></td><td>실행 / 환경 스크립트</td></tr><tr><td><code>scripts/issac_sim.bash</code></td><td>Motion, Isaac Sim, 웹 UI를 한꺼번에 띄웁니다</td></tr><tr><td><code>scripts/install/isaacsim.bash</code></td><td>Isaac Sim을 설치합니다</td></tr></tbody></table><h2 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h2><table tabindex="0"><thead><tr><th>옵션</th><th>의미</th></tr></thead><tbody><tr><td><code>--world &lt;name&gt;</code></td><td>불러올 월드. 기본 <code>empty</code>. <a href="#worlds">월드</a> 참조</td></tr><tr><td><code>--headless</code></td><td>Isaac Sim 창 없이 실행합니다</td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS 네트워크 인터페이스. 기본 <code>lo</code></td></tr></tbody></table><p><code>scripts/issac_sim.bash</code> 는 <code>--vision</code>(Vision 스택 실행)과 <code>--ros</code>(ROS 2 드라이버와 RViz 실행)도 받습니다.</p><h2 id="worlds" tabindex="-1">월드 <a class="header-anchor" href="#worlds" aria-label="Permalink to &quot;월드 {#worlds}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>종류</th><th><code>--world</code></th><th>비고</th></tr></thead><tbody><tr><td>평지</td><td><code>empty</code>, <code>raceway</code>, <code>maze</code></td><td>내려받을 것 없음</td></tr><tr><td>Isaac Sim 기본 제공</td><td><code>grid</code>, <code>office</code>, <code>hospital</code>, <code>simple_room</code>, <code>warehouse</code>, <code>depot</code>, <code>warehouse_shelves</code>, <code>warehouse_forklifts</code></td><td>처음 쓸 때 NVIDIA에서 내려받습니다</td></tr><tr><td>패키지 포함</td><td><code>stairs_course</code>, <code>two_floor_office</code>, <code>terrain_park</code></td><td>오프라인에서도 동작합니다</td></tr></tbody></table><table tabindex="0"><thead><tr><th>패키지 포함 월드</th><th>내용</th></tr></thead><tbody><tr><td><code>stairs_course</code></td><td>32 x 16 m 홀. 계단(0.10 m, 0.15 m 높이), 10° / 15° / 20° 경사로, 울퉁불퉁한 블록, 징검돌, 연석</td></tr><tr><td><code>two_floor_office</code></td><td>꺾인 계단(0.15 m x 20단)으로 이어진 2층 건물. 층마다 방을 도는 동선이 있습니다</td></tr><tr><td><code>terrain_park</code></td><td>40 x 40 m 야외 공원. 피라미드 계단, 거친 지형, 15° 언덕, 계단과 경사로가 붙은 광장</td></tr></tbody></table><h3 id="내-usd-쓰기" tabindex="-1">내 USD 쓰기 <a class="header-anchor" href="#내-usd-쓰기" aria-label="Permalink to &quot;내 USD 쓰기&quot;">​</a></h3><p><code>rbq_simulator/rbq_sim/rbq_sim/worlds.py</code> 의 <code>WORLDS</code> 에 항목을 추가하고 이름으로 실행합니다:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spawn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># x, y, z [m], yaw [rad]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/my_site.usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 절대경로, 또는 file:// / omniverse:// 주소</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_site</span></span></code></pre></div><p>USD가 평지 바닥을 대신하므로 USD 안에 충돌 판정이 있는 바닥이 있어야 합니다. 로봇은 시작 위치에서 앉은 자세로 시작합니다. 바닥 높이가 0이 아니면 그만큼 <code>z</code> 를 올립니다.</p><h2 id="rbq-스택-전체와-함께-실행-local" tabindex="-1">RBQ 스택 전체와 함께 실행 (Local) <a class="header-anchor" href="#rbq-스택-전체와-함께-실행-local" aria-label="Permalink to &quot;RBQ 스택 전체와 함께 실행 (Local)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Isaac Sim 설치 (최초 1회, 일반 사용자로 실행. apt 단계에서만 sudo를 묻습니다)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install/isaacsim.bash</span></span></code></pre></div><p><strong>한꺼번에</strong> — Motion, Isaac Sim, 웹 UI를 터미널 탭으로 나눠 띄웁니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span></code></pre></div><p><strong>따로</strong> — RBQ 스택과 시뮬레이터를 터미널 두 개에서 띄웁니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/start_motion.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # 터미널 1, sudo를 묻습니다</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 터미널 2</span></span></code></pre></div><p>브라우저에서 <code>http://127.0.0.1:8080</code> 을 열어 로봇을 조종합니다(<code>rb</code> / <code>rainbow2026</code> 으로 로그인). 처음 실행할 때는 Isaac Sim이 셰이더 캐시를 만드느라 몇 분 걸립니다.</p><h2 id="제어-주기" tabindex="-1">제어 주기 <a class="header-anchor" href="#제어-주기" aria-label="Permalink to &quot;제어 주기&quot;">​</a></h2><p>Isaac Sim은 실시간보다 느리게 돕니다. 창 없이 약 0.85배, 창을 띄우면 약 0.6배입니다. 시뮬레이터가 Motion을 시뮬레이션 시간에 맞춰 돌리므로 로봇 소프트웨어는 여전히 2 ms 제어 주기를 봅니다:</p><ul><li>물리는 1 kHz로 돕니다. 시뮬레이션 시간 2 ms마다 상태를 보내고, Motion의 응답을 받은 뒤에 다음으로 넘어갑니다.</li><li>그래서 렌더링이 아무리 느려도 Motion은 시뮬레이션 시간 2 ms마다 정확히 한 번 제어를 돕니다. 화면에서 느리게 보일 뿐 동작은 같습니다.</li><li>콘솔에 5초마다 <code>lockstep ON acked 1472/1472 timeouts 0</code> 같은 줄이 찍힙니다. <code>timeouts 0</code> 이면 건너뛴 제어 주기가 없다는 뜻입니다.</li><li>Motion이 없으면 시뮬레이터는 앉은 자세를 유지하고 실시간 속도로 돕니다.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS 네트워킹</p><p>시뮬레이터는 RBQ 스택과 루프백 인터페이스(<code>lo</code>)에서 <strong>DDS 도메인 0</strong>을 공유합니다. 대부분의 PC는 <code>lo</code> 에 멀티캐스트가 없어서 <code>run.bash</code> 가 <code>rbq_simulator/rbq_sim/cyclonedds_sim.xml</code> 을 씁니다. 시뮬레이터는 한 번에 하나만 띄웁니다. Isaac Sim, MuJoCo, Gazebo는 같은 토픽을 씁니다.</p></div></div><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo</a> — MuJoCo 시뮬레이터</li><li><a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo</a> — Ignition Gazebo 시뮬레이터</li><li><a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab</a> — 같은 로봇 모델을 쓰는 강화학습 환경</li><li><a href="/RBQ/nightly/ko/software/simulator/overview.html">시뮬레이터 개요</a></li></ul>`,33)])])}const u=i(d,[["render",l]]);export{m as __pageData,u as default};
